SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS `content_documents` (`coddocumento` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`chave_idempotencia` VARCHAR(191) NOT NULL,`codigo` VARCHAR(120) NOT NULL,`titulo` VARCHAR(500) NOT NULL,`descricao` TEXT NULL,`tipo_documento` VARCHAR(80) NULL,`codusuario_criador` BIGINT UNSIGNED NOT NULL,`codunidade` BIGINT UNSIGNED NULL,`origem_entidade` VARCHAR(100) NULL,`origem_id` VARCHAR(100) NULL,`status` VARCHAR(20) NOT NULL DEFAULT 'RASCUNHO',`versao_atual` INT UNSIGNED NOT NULL DEFAULT 0,`criado_em` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,`atualizado_em` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`coddocumento`),UNIQUE KEY `UK_CONTENT_DOCUMENT_IDEMP` (`chave_idempotencia`),UNIQUE KEY `UK_CONTENT_DOCUMENT_CODIGO` (`codigo`),KEY `IX_CONTENT_DOCUMENT_STATUS` (`status`,`atualizado_em`),KEY `IX_CONTENT_DOCUMENT_ORIGEM` (`origem_entidade`,`origem_id`),CONSTRAINT `FK_CONTENT_DOCUMENT_USER` FOREIGN KEY (`codusuario_criador`) REFERENCES `usuarios` (`codusuario`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS `content_versions` (`codversaodocumento` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`coddocumento` BIGINT UNSIGNED NOT NULL,`chave_idempotencia` VARCHAR(191) NOT NULL,`versao` INT UNSIGNED NOT NULL,`nome_arquivo` VARCHAR(500) NULL,`mime_type` VARCHAR(150) NULL,`tamanho_bytes` BIGINT UNSIGNED NULL,`hash_sha256` CHAR(64) NULL,`storage_key` VARCHAR(500) NULL,`observacao` TEXT NULL,`codusuario` BIGINT UNSIGNED NOT NULL,`criado_em` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`codversaodocumento`),UNIQUE KEY `UK_CONTENT_VERSION_IDEMP` (`chave_idempotencia`),UNIQUE KEY `UK_CONTENT_VERSION_NUMBER` (`coddocumento`,`versao`),KEY `IX_CONTENT_VERSION_HASH` (`coddocumento`,`hash_sha256`),CONSTRAINT `FK_CONTENT_VERSION_DOC` FOREIGN KEY (`coddocumento`) REFERENCES `content_documents` (`coddocumento`),CONSTRAINT `FK_CONTENT_VERSION_USER` FOREIGN KEY (`codusuario`) REFERENCES `usuarios` (`codusuario`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
