INSERT INTO `workflow_definicoes` (`codigo`,`nome`,`versao`,`publicado`,`ativo`) VALUES ('CONTENT_APPROVAL','Aprovação de conteúdo Green Content',1,1,1) ON DUPLICATE KEY UPDATE `nome`=VALUES(`nome`),`publicado`=1,`ativo`=1;
