INSERT INTO `registros_migracao` (`codigo_migracao`,`origem`,`destino`,`tipo`,`versao`,`status`,`quantidade_registros`,`iniciada_em`,`concluida_em`,`detalhes`) VALUES ('GREEN_CONTENT_189','Green Content/GED','content_documents/content_versions/CONTENT_APPROVAL','ESTRUTURA','4.0.1','CONCLUIDA',0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,JSON_OBJECT('legado_preservado',TRUE,'workflow_integrado',TRUE,'idempotente',TRUE)) ON DUPLICATE KEY UPDATE `status`=VALUES(`status`),`concluida_em`=VALUES(`concluida_em`),`detalhes`=VALUES(`detalhes`);
